function toggleTodo(id, completed) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  todo.completed = completed;
  saveTodos();
  render();
}

/**
 * Sets every todo to the same completed state.
 * @planks("the user marks all todos as complete")
 * @planks("Mark-all checkbox completes every todo")
 * @planks("Mark-all checkbox reflects all-complete state")
 */
function toggleAll(completed) {
  todos.forEach((t) => {
    t.completed = completed;
